// خادم عداد — Node ESM من الوحدات المدمجة فقط (node:http, node:fs, node:path)
// يخدم index.html كصفحة رئيسية ويوفر API حقيقيًا للعداد في ذاكرة الخادم على المنفذ 3000.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';

const PORT = 3000;

// حالة العداد محفوظة في ذاكرة الخادم (لا localStorage ولا عداد محلي بديل)
let count = 0;

// تحديد مجلد السكربت لخدمة index.html بجواره مهما كان مجلد التشغيل
const scriptDir = path.dirname(process.argv[1] || process.cwd());
const INDEX_CANDIDATES = [
  path.join(scriptDir, 'index.html'),
  path.join(process.cwd(), 'index.html')
];

function findIndexPath() {
  for (const candidate of INDEX_CANDIDATES) {
    try {
      if (fs.statSync(candidate).isFile()) return candidate;
    } catch {
      // المتابعة إلى المرشح التالي
    }
  }
  return INDEX_CANDIDATES[0];
}

const INDEX_PATH = findIndexPath();

function sendJson(res, statusCode, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
    'Cache-Control': 'no-store'
  });
  res.end(body);
}

function sendNotFound(res) {
  sendJson(res, 404, { error: 'Not Found' });
}

function sendIndex(res) {
  fs.readFile(INDEX_PATH, (err, data) => {
    if (err) {
      sendJson(res, 500, { error: 'Internal Server Error' });
      return;
    }
    res.writeHead(200, {
      'Content-Type': 'text/html; charset=utf-8',
      'Content-Length': data.length,
      'Cache-Control': 'no-store'
    });
    res.end(data);
  });
}

// استهلاك أي جسم طلب قادم قبل الرد (طلبات POST هنا بلا جسم)
function drain(req, done) {
  req.resume();
  if (req.readableEnded) {
    done();
  } else {
    req.on('end', done);
    req.on('error', done);
  }
}

const server = http.createServer((req, res) => {
  let pathname;
  try {
    pathname = new URL(req.url, `http://${req.headers.host || 'localhost'}`).pathname;
  } catch {
    sendNotFound(res);
    return;
  }

  // الصفحة الرئيسية: index.html
  if (req.method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
    sendIndex(res);
    return;
  }

  // API: القيمة الحالية للعداد
  if (req.method === 'GET' && pathname === '/api/count') {
    sendJson(res, 200, { count });
    return;
  }

  // API: زيادة العداد بمقدار 1 وإعادة القيمة الجديدة
  if (req.method === 'POST' && pathname === '/api/increment') {
    drain(req, () => {
      count += 1;
      sendJson(res, 200, { count });
    });
    return;
  }

  // API: إعادة العداد إلى صفر
  if (req.method === 'POST' && pathname === '/api/reset') {
    drain(req, () => {
      count = 0;
      sendJson(res, 200, { count });
    });
    return;
  }

  // أي مسار آخر: 404
  sendNotFound(res);
});

server.on('error', (err) => {
  console.error('Server error:', err.message);
  process.exitCode = 1;
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});

